import openpyxl
wb=openpyxl.load_workbook('output.xlsx',data_only=False)
ws=wb.active
# top row sizes
sizes={ws.cell(row=2,column=c).value:(c) for c in range(2,13)}
# ratings per row
ratings={r:ws.cell(row=r,column=13).value for r in range(3,9)}
S2=ws['S2'].value
print('S2=',S2)
for r in range(2,7):
    P=ws.cell(row=r,column=16).value
    vals=[]
    for rr in range(3,9):
        if ratings[rr]!=S2: continue
        for c in range(2,13):
            if sizes[c]==P:
                v=ws.cell(row=rr,column=c).value
                if v is not None:
                    vals.append(v)
    avg=sum(vals)/len(vals) if vals else ''
    print('P',P,'->',avg, vals)
"

